<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('recruiter');$user=current_user();$flashes=render_flashes();$currentPage='search';$pageTitle='Find Candidates';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$recruiterId=(int)($user['id']??$user['user_id']??0);if($recruiterId<=0){http_response_code(403);exit('Invalid Recruiter account.');}
$skill=trim((string)($_GET['skill']??''));$province=trim((string)($_GET['province']??'Gauteng'));$city=trim((string)($_GET['city']??''));$verification=trim((string)($_GET['verification']??'verified'));$maxAge=max(0,(int)($_GET['max_age_days']??180));$scarce=isset($_GET['scarce_only'])?1:0;$taxonomy=rc_taxonomy_version($conn);$rows=[];$ready=rc_has_table($conn,'candidate_profiles')&&rc_has_table($conn,'candidate_consents')&&rc_has_table($conn,'candidate_skills')&&rc_has_table($conn,'skills');
if($ready){$w=["cc.consent_type='recruiter_discovery'","cc.status='consented'","(cc.expires_at IS NULL OR cc.expires_at>NOW())"];$p=[];$types='';if($verification!==''){$w[]='cp.verification_status=?';$p[]=$verification;$types.='s';}if($province!==''){$w[]='cp.province=?';$p[]=$province;$types.='s';}if($city!==''){$w[]='cp.city=?';$p[]=$city;$types.='s';}if($maxAge>0){$w[]='cp.last_verified_at>=DATE_SUB(NOW(),INTERVAL ? DAY)';$p[]=$maxAge;$types.='i';}if($skill!==''){$w[]="EXISTS(SELECT 1 FROM candidate_skills x JOIN skills y ON y.id=x.skill_id WHERE x.candidate_id=cp.user_id AND x.verification_status='verified' AND (y.name LIKE ? OR y.normalized_name LIKE ?))";$like='%'.$skill.'%';$p[]=$like;$p[]=$like;$types.='ss';}if($scarce){$w[]="EXISTS(SELECT 1 FROM candidate_skills x JOIN skills y ON y.id=x.skill_id WHERE x.candidate_id=cp.user_id AND x.verification_status='verified' AND y.is_scarce=1)";} $sql="SELECT cp.user_id,cp.headline,cp.province,cp.city,cp.years_experience,cp.availability_status,cp.verification_status,cp.last_verified_at,u.first_name,u.last_name,u.email,GROUP_CONCAT(DISTINCT CASE WHEN cs.verification_status='verified' THEN s.name END ORDER BY s.is_scarce DESC,s.name SEPARATOR ', ') skills FROM candidate_profiles cp JOIN users u ON u.id=cp.user_id JOIN candidate_consents cc ON cc.candidate_id=cp.user_id LEFT JOIN candidate_skills cs ON cs.candidate_id=cp.user_id LEFT JOIN skills s ON s.id=cs.skill_id WHERE ".implode(' AND ',$w)." GROUP BY cp.user_id,cp.headline,cp.province,cp.city,cp.years_experience,cp.availability_status,cp.verification_status,cp.last_verified_at,u.first_name,u.last_name,u.email ORDER BY cp.last_verified_at DESC,cp.years_experience DESC";$s=$conn->prepare($sql);if($types!=='')$s->bind_param($types,...$p);$s->execute();$r=$s->get_result();while($x=$r->fetch_assoc())$rows[]=$x;$s->close();}
require __DIR__.'/_layout_start.php';?>
<div class="rc-page-header"><span class="rc-eyebrow">Structured Talent Search</span><h2>Find Candidates</h2><p>Search verified, consented talent by skill, location, recency and scarcity.</p></div><?php if(!$ready):?><div class="rc-alert rc-alert--warning"><i class="fas fa-database"></i><div>Recruiter tables are not installed. Review database/recruiter_portal.sql.</div></div><?php endif;?>
<form class="rc-search" method="get"><div class="rc-field rc-grow"><label>Skill / Technology</label><input name="skill" value="<?=e($skill)?>" placeholder="Java, AWS, Azure, Kubernetes"></div><div class="rc-field"><label>Province</label><select name="province"><option value="">Any province</option><?php foreach(['Gauteng','Western Cape','KwaZulu-Natal','Eastern Cape','Free State','Limpopo','Mpumalanga','North West','Northern Cape'] as $v):?><option value="<?=e($v)?>" <?=$province===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div class="rc-field"><label>City</label><input name="city" value="<?=e($city)?>" placeholder="Any city"></div><div class="rc-field"><label>Verification</label><select name="verification"><option value="">Any</option><option value="verified" <?=$verification==='verified'?'selected':''?>>Verified</option><option value="pending" <?=$verification==='pending'?'selected':''?>>Pending</option></select></div><div class="rc-field"><label>Recency</label><select name="max_age_days"><?php foreach([30=>'30 days',90=>'90 days',180=>'6 months',365=>'12 months',0=>'Any age'] as $d=>$lab):?><option value="<?=$d?>" <?=$maxAge===$d?'selected':''?>><?=e($lab)?></option><?php endforeach;?></select></div><label class="rc-check"><input type="checkbox" name="scarce_only" value="1" <?=$scarce?'checked':''?>><span>Scarce skills only</span></label><button class="rc-btn rc-btn--primary"><i class="fas fa-magnifying-glass"></i> Search</button></form>
<div class="rc-summary"><div><strong><?=number_format(count($rows))?> match(es)</strong><span>Taxonomy <?=e($taxonomy)?></span></div><div><?php if($skill!==''):?><b><?=e($skill)?></b><?php endif;?><?php if($province!==''):?><b><?=e($province)?></b><?php endif;?></div></div>
<?php if(!$rows):?><div class="rc-card"><div class="rc-empty"><i class="fas fa-users-viewfinder"></i><strong>No eligible matches</strong><span>No candidate satisfies the selected scope, consent and verification rules.</span></div></div><?php else:?><div class="rc-results"><?php foreach($rows as $x):$f=trim((string)$x['first_name']);$l=trim((string)$x['last_name']);$name=trim($f.' '.$l)?:'Candidate';?><article class="rc-match"><div class="rc-match__head"><div class="rc-avatar rc-avatar--large"><?=e(rc_initials($f,$l))?></div><div class="rc-match__identity"><div><strong><?=e($name)?></strong><span class="rc-status rc-status--success">Verified</span></div><p><?=e((string)($x['headline']?:'Candidate'))?></p><small><i class="fas fa-location-dot"></i> <?=e(trim((string)$x['city'].', '.(string)$x['province'],' ,'))?> · <i class="fas fa-briefcase"></i> <?=number_format((int)$x['years_experience'])?> years</small></div><div class="rc-score"><strong>100%</strong><span>Match</span></div></div><div class="rc-match__body"><span class="rc-label">Verified skills</span><div class="rc-chips"><?php foreach(array_filter(array_map('trim',explode(',',(string)$x['skills']))) as $sk):?><b><?=e($sk)?></b><?php endforeach;?></div><div class="rc-triples"><div><span>Evidence</span><strong>Verified profile and skill records</strong></div><div><span>Recency</span><strong><?=e(rc_datetime($x['last_verified_at']))?></strong></div><div><span>Missing criteria</span><strong class="rc-good">None</strong></div></div></div><div class="rc-match__foot"><span><i class="fas fa-user-shield"></i> Recruiter-discovery consent valid</span><div><a class="rc-btn rc-btn--secondary rc-btn--small" href="<?=url('recruiter/candidate_view.php?id='.(int)$x['user_id'])?>">View Profile</a><a class="rc-btn rc-btn--primary rc-btn--small" href="<?=url('recruiter/shortlists.php?candidate_id='.(int)$x['user_id'].'&skill='.urlencode($skill).'&province='.urlencode($province).'&verification='.urlencode($verification).'&max_age_days='.$maxAge.'&scarce_only='.$scarce.'&taxonomy_version='.urlencode($taxonomy))?>"><i class="fas fa-plus"></i> Shortlist</a></div></div></article><?php endforeach;?></div><?php endif;?>
<?php require __DIR__.'/_layout_end.php';?>